  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function normalizeTags(tags) {
    if (Array.isArray(tags)) {
      return tags.map((tag) => String(tag).trim()).filter(Boolean);
    }
    if (typeof tags === 'string') {
      return tags
        .split(/[,，、\n]+/)
        .map((tag) => tag.trim())
        .filter(Boolean);
    }
    return [];
  }

  function normalizeProject(project) {
    const source = project && typeof project === 'object' ? project : {};
    const status = PROJECT_STATUSES.includes(source.status) ? source.status : '待补充';

    return {
      id: source.id || generateId(),
      name: String(source.name || '').trim(),
      url: String(source.url || '').trim(),
      description: String(source.description || '').trim(),
      role: String(source.role || '').trim(),
      tools: String(source.tools || '').trim(),
      outcome: String(source.outcome || '').trim(),
      createdAt: source.createdAt || '',
      tags: normalizeTags(source.tags),
      status,
      groupId: source.groupId || null
    };
  }

  function normalizeNote(note) {
    const source = note && typeof note === 'object' ? note : {};
    return {
      id: source.id || generateId('n'),
      title: String(source.title || '').trim(),
      excerpt: String(source.excerpt || '').trim(),
      tags: normalizeTags(source.tags),
      date: source.date || '',
      readTime: source.readTime || '5 分钟阅读',
      category: String(source.category || '其他').trim(),
      url: source.url || ''
    };
  }

  function normalizePortfolioData(data) {
    const source = data && typeof data === 'object' ? data : {};
    const sourceCategories = Array.isArray(source.categories)
      ? source.categories.filter((category) => category && typeof category === 'object')
      : [];

    const categories = sourceCategories.map((sourceCategory) => {
      const defaultCategory = DEFAULT_DATA.categories.find((category) => category.id === sourceCategory.id);

      const groups = Array.isArray(sourceCategory?.groups)
        ? sourceCategory.groups.map(g => ({
            id: String(g.id || generateId('g')),
            name: String(g.name || '未命名分组').trim()
          }))
        : [];

      const projects = Array.isArray(sourceCategory?.projects)
        ? sourceCategory.projects.map(normalizeProject)
        : [];

      return {
        id: String(sourceCategory.id || generateId('c')),
        name: String(sourceCategory.name || defaultCategory?.name || '未命名分类').trim(),
        groups,
        projects
      };
    });

    const existingCategoryIds = new Set(categories.map((category) => category.id));
    DEFAULT_DATA.categories.forEach((defaultCategory) => {
      if (existingCategoryIds.has(defaultCategory.id)) return;
      categories.push({
        id: defaultCategory.id,
        name: defaultCategory.name,
        groups: [],
        projects: []
      });
    });

    return {
      categories,
      notes: Array.isArray(source.notes) ? source.notes.map(normalizeNote) : [],
      featuredWorks: Array.isArray(source.featuredWorks) ? source.featuredWorks : [],
      featuredNotes: Array.isArray(source.featuredNotes) ? source.featuredNotes : []
    };
  }

  function isFirebaseConfigured() {
    return Boolean(
      FIREBASE_CONFIG.apiKey &&
      FIREBASE_CONFIG.authDomain &&
      FIREBASE_CONFIG.projectId &&
      FIREBASE_CONFIG.appId
    );
  }

  async function loadModules() {
    if (!cachedModulesPromise) {
      cachedModulesPromise = Promise.all([
        import(`https://www.gstatic.com/firebasejs/${FIREBASE_VERSION}/firebase-app.js`),
        import(`https://www.gstatic.com/firebasejs/${FIREBASE_VERSION}/firebase-auth.js`),
        import(`https://www.gstatic.com/firebasejs/${FIREBASE_VERSION}/firebase-firestore.js`)
      ]).then(([appModule, authModule, firestoreModule]) => {
        modulesCache = {
          initializeApp: appModule.initializeApp,
          getAuth: authModule.getAuth,
          onAuthStateChanged: authModule.onAuthStateChanged,
          setPersistence: authModule.setPersistence,
          browserLocalPersistence: authModule.browserLocalPersistence,
          signInWithEmailAndPassword: authModule.signInWithEmailAndPassword,
          signOut: authModule.signOut,
          getFirestore: firestoreModule.getFirestore,
          doc: firestoreModule.doc,
          getDoc: firestoreModule.getDoc,
          setDoc: firestoreModule.setDoc
        };

        return modulesCache;
      });
    }

    return cachedModulesPromise;
  }

  async function initFirebase() {
    if (initResult && initResult.ok) {
      return initResult;
    }

    if (initPromise) {
      return initPromise;
    }

    initPromise = (async () => {
      if (!isFirebaseConfigured()) {
        initResult = {
          ok: false,
          error: 'Firebase 配置缺失，请先补全 js/firebase-portfolio.js 中的 FIREBASE_CONFIG。'
        };
        return initResult;
      }

      try {
        let timer;
        const modules = await Promise.race([
          loadModules(),
          new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('连接云端超时')), 15000); })
        ]).finally(() => clearTimeout(timer));
        firebaseApp = modules.initializeApp(FIREBASE_CONFIG);
        auth = modules.getAuth(firebaseApp);
        db = modules.getFirestore(firebaseApp);

        if (modules.setPersistence && modules.browserLocalPersistence) {
          modules.setPersistence(auth, modules.browserLocalPersistence).catch(() => {});
        }

        initResult = {
          ok: true,
          auth,
          db,
          modules
        };
        return initResult;
      } catch (error) {
        cachedModulesPromise = null;
        initPromise = null;
        initResult = {
          ok: false,
          error: '云端连接失败，请开启 VPN 后重试。已发布内容不受影响。'
        };
        return initResult;
      }
    })();

    return initPromise;
  }

  function getAuthReady() {
    return auth;
  }

  function getDbReady() {
    return db;
  }

  function getPortfolioDocRef() {
    if (!db || !modulesCache) return null;
    return modulesCache.doc(db, PORTFOLIO_DOC_PATH[0], PORTFOLIO_DOC_PATH[1]);
  }

  async function ensureAdminSeed() {
    const context = await initFirebase();
    if (!context.ok || !auth || !db) {
      return context;
    }

    const user = auth.currentUser;
    if (!user || user.email !== ADMIN_EMAIL) {
      return { ok: false, error: '当前未以管理员身份登录，无法初始化云端数据。' };
    }

    const ref = getPortfolioDocRef();
    const snapshot = await context.modules.getDoc(ref);
    if (snapshot.exists()) {
      return { ok: true, seeded: false };
    }

    await context.modules.setDoc(ref, normalizePortfolioData(DEFAULT_DATA));
    return { ok: true, seeded: true };
  }

  async function loadPortfolioData() {
    if (!managementMode) {
      try {
        const snapshot = globalThis.portfolioPublication || PUBLISHED_SNAPSHOT;
        if (!snapshot?.version || !Array.isArray(snapshot.data?.categories) || !Array.isArray(snapshot.data?.notes)) throw new Error('发布内容格式不完整');
        globalThis.portfolioPublication = snapshot;
        return { ok: true, data: normalizePortfolioData(clone(snapshot.data)) };
      } catch (error) {
        return { ok: false, error: '已发布内容加载失败，请刷新页面重试。' };
      }
    }
    const context = await initFirebase();
    if (!context.ok || !db) {
      return context;
    }

    try {
      const ref = getPortfolioDocRef();
      let timer;
      const snapshot = await Promise.race([
        context.modules.getDoc(ref),
        new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('读取云端超时，请检查 VPN 后重试')), 15000); })
      ]).finally(() => clearTimeout(timer));
      if (!snapshot.exists()) {
        return {
          ok: false,
          empty: true,
          error: 'Firestore 作品集文档不存在，请先让管理员登录一次完成初始化。'
        };
      }

      return {
        ok: true,
        data: normalizePortfolioData(snapshot.data())
      };
    } catch (error) {
      return {
        ok: false,
        error: `读取 Firestore 失败：${error && error.message ? error.message : '未知错误'}`
      };
    }
  }

  async function savePortfolioData(data) {
    const context = await initFirebase();
    if (!context.ok || !db) {
      return context;
    }

    const user = auth && auth.currentUser;
    if (!user || user.email !== ADMIN_EMAIL) {
      return {
        ok: false,
        error: '只有管理员登录后才能写入 Firestore。'
      };
    }

    try {
      await context.modules.setDoc(getPortfolioDocRef(), normalizePortfolioData(data), { merge: true });
      globalThis.dispatchEvent?.(new Event('portfolio-draft-saved'));
      return { ok: true };
    } catch (error) {
      return {
        ok: false,
        error: `保存 Firestore 失败：${error && error.message ? error.message : '未知错误'}`
      };
    }
  }

  async function signInAdmin(password) {
    const context = await initFirebase();
    if (!context.ok || !auth) {
      return context;
    }

    try {
      const result = await context.modules.signInWithEmailAndPassword(auth, ADMIN_EMAIL, password);
      if (!isAdminUser(result.user)) return { ok: false, error: '只有管理员可以管理内容。' };
      managementMode = true;
      return {
        ok: true,
        user: result.user
      };
    } catch (error) {
      return {
        ok: false,
        error: error && error.message ? error.message : '登录失败'
      };
    }
  }

  async function signOutAdmin() {
    managementMode = false;
    const context = await initFirebase();
    if (!context.ok || !auth) {
      return context;
    }

    try {
      await context.modules.signOut(auth);
      return { ok: true };
    } catch (error) {
      return {
        ok: false,
        error: error && error.message ? error.message : '退出失败'
      };
    }
  }

  function onAuthChange(callback) {
    if (authListenersBound) {
      return;
    }

    initFirebase().then((context) => {
      if (!context.ok || !auth) return;
      authListenersBound = true;
      context.modules.onAuthStateChanged(auth, callback);
    });
  }

  function isAdminUser(user) {
    return Boolean(user && user.email === ADMIN_EMAIL);
  }

  function generateId(prefix = 'p') {
    return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
  }

